const fetch = require('node-fetch');

const getExercise = async (muscleChoice) => {
  const url = `https://exercisedb.p.rapidapi.com/exercises/bodyPart/${muscleChoice}`;
  const options = {
    method: "GET",
    headers: {
      "X-RapidAPI-Key": "57996be828msh986f446112d7c93p1e56fajsn95c27087f48a",
      "X-RapidAPI-Host": "exercisedb.p.rapidapi.com",
    },
  };

  try {
    const response = await fetch(url, options);
    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Error fetching exercise data:", error);
    return null;
  }
};

// Exemplo de uso
const muscleChoice = 'arm'; // Substitua por qualquer grupo muscular
getExercise(muscleChoice).then((data) => {
  console.log(data); // Aqui você pode manipular os dados recebidos da API
});
